const input = $input.item.json || {};
const msg = input.message || {};

const rawText = String(
  msg.text ||
  msg.caption ||
  input.text ||
  input.rawText ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

const text = normalize(rawText);

const document = msg.document || null;
const photo = Array.isArray(msg.photo) && msg.photo.length ? msg.photo[msg.photo.length - 1] : null;
const video = msg.video || null;
const audio = msg.audio || msg.voice || null;
const sticker = msg.sticker || null;
const location = msg.location || null;
const contact = msg.contact || null;

const hasDocument = Boolean(document);
const hasPhoto = Boolean(photo);
const hasVideo = Boolean(video);
const hasAudio = Boolean(audio);
const hasSticker = Boolean(sticker);
const hasLocation = Boolean(location);
const hasContact = Boolean(contact);
const hasAttachment = hasDocument || hasPhoto || hasVideo || hasAudio || hasSticker || hasLocation || hasContact;

const fileId = document?.file_id || photo?.file_id || video?.file_id || audio?.file_id || sticker?.file_id || '';
const fileName = document?.file_name || video?.file_name || audio?.file_name || '';
const mimeType = document?.mime_type || video?.mime_type || audio?.mime_type || '';
const fileSize = document?.file_size || video?.file_size || audio?.file_size || photo?.file_size || sticker?.file_size || 0;
const links = rawText.match(/https?:\/\/[^\s]+/gi) || [];

let attachmentKind = 'none';
if (hasDocument) attachmentKind = 'document';
else if (hasPhoto) attachmentKind = 'photo';
else if (hasVideo) attachmentKind = 'video';
else if (hasAudio) attachmentKind = 'audio';
else if (hasSticker) attachmentKind = 'sticker';
else if (hasLocation) attachmentKind = 'location';
else if (hasContact) attachmentKind = 'contact';

let route = 'ai';
let routeReason = 'default_ai';

// Master chỉ giữ route legacy cực ít. Mọi thứ còn lại đưa qua AI Advanced
// để AI/Tool Router xử lý text, caption, file, ảnh, link, v.v.
if (text.startsWith('/gold')) {
  route = 'gold';
  routeReason = 'slash_gold';
} else if (text.startsWith('/news help')) {
  route = 'news_help';
  routeReason = 'slash_news_help';
} else if (text.startsWith('/news')) {
  route = 'news';
  routeReason = 'slash_news';
}

return [{
  json: {
    ...input,
    route,
    routeReason,
    chatId: msg.chat?.id || input.chatId || '',
    rawText,
    text: rawText,
    normalizedText: text,
    message: msg,
    payload: input,
    hasAttachment,
    attachmentKind,
    hasDocument,
    hasPhoto,
    hasVideo,
    hasAudio,
    hasSticker,
    hasLocation,
    hasContact,
    fileId,
    fileName,
    mimeType,
    fileSize,
    links,
    document,
    photo,
    video,
    audio,
    sticker,
    location,
    contact
  }
}];
